        passes: n,
        accesses: n,
        draws: 0,
        dependencies: n,
        initial_ranges: 0,
        name_bytes: n + 1,
        upload_bytes: 0,
        edges: n,
        segments: 2 * n + 1,
        readers: n,
    }
}

fn report(scenario: &str, n: usize, raw: &[u128]) {
