}

fn dependencies(n: usize) {
    let mut pool = GraphPool::new(capacity(n), 1).unwrap();
    let mut handles = Vec::with_capacity(n);
    let mut raw = Vec::with_capacity(9);
    for sample in 0..WARMUP + 9 {
        let mut graph = pool.begin().unwrap();
        handles.clear();
        for _ in 0..n {
            handles.push(graph.declare_pass("p", PassKind::Copy, &[], true).unwrap());
        }
        let started = Instant::now();
        for p in 1..n {
            graph.depends_on(handles[p], handles[p - 1]).unwrap();
        }
        let elapsed = started.elapsed().as_nanos();
        black_box(&graph);
        if sample >= WARMUP { raw.push(elapsed); }
    }
    report("explicit_dependency_insertion", n, &raw);
}

fn fallback_compile(n: usize, culled_writes: bool) {
    let mut pool = GraphPool::new(capacity(n + 1), 1).unwrap();
    let mut handles = Vec::with_capacity(n);
    let mut raw = Vec::with_capacity(9);
    for sample in 0..WARMUP + 9 {
        let mut graph = pool.begin().unwrap();
        let buffer = graph.buffer("b", BufferDesc { size: n as u64 * 4 }).unwrap();
        handles.clear();
        for offset in 0..n {
            let start = offset as u64 * 4;
            handles.push(graph.declare_pass("p", PassKind::Copy, &[Access {
                resource: buffer.into(), range: AccessRange::Buffer(start..start + 4),
                kind: AccessKind::Write, purpose: AccessPurpose::CopyDestination,
            }], !culled_writes).unwrap());
        }
        if culled_writes {
            graph.declare_pass("w", PassKind::Copy, &[Access {
                resource: buffer.into(), range: AccessRange::Buffer(0..n as u64 * 4),
                kind: AccessKind::Write, purpose: AccessPurpose::CopyDestination,
            }], true).unwrap();
        } else {
            for i in 0..n - 1 { graph.depends_on(handles[i], handles[i + 1]).unwrap(); }
        }
        graph.export_buffer(buffer).unwrap();
        let started = Instant::now();
        let plan = graph.compile().unwrap();
        let elapsed = started.elapsed().as_nanos();
        assert_eq!(plan.pass_count(), if culled_writes { 1 } else { n });
        black_box(&plan);
        if sample >= WARMUP { raw.push(elapsed); }
    }
    report(if culled_writes { "culled_overwritten_writers" } else { "backward_disjoint_chain_compile" }, n, &raw);
}

fn engine_graph(meshes: usize, draws: usize, dead_branch: bool) {
    let mut engine = Engine::new(EngineCapacity { meshes, materials: 1, retired_mesh_versions: 0 }).unwrap();
    let material = engine.create_material(Material::default()).unwrap();
    let mesh_handles: Vec<_> = (0..meshes).map(|_| engine.create_mesh(MeshData::new(
        &[[-0.5, -0.5, 0.5], [0.5, -0.5, 0.5], [0.0, 0.5, 0.5]].map(|position| Vertex { position, color: [1.0; 4] }),
        &[0, 1, 2],
    ).unwrap()).unwrap()).collect();
    let draw_input: Vec<_> = (0..draws).map(|i| Draw { mesh: mesh_handles[i % meshes], material, world_from_model: IDENTITY }).collect();
    let snapshots = SnapshotPool::new(draws, 1).unwrap();
    let view = View { width: 32, height: 24, clip_from_world: IDENTITY, clear_color: [0.0, 0.0, 0.0, 1.0] };
    let captured = engine.snapshot(&snapshots, &view, &draw_input).unwrap();
    let mut pool = GraphPool::new(GraphCapacity {
        resources: 2 * meshes + 10, passes: 2 * meshes + 16, accesses: 4 * meshes + 64,
        draws, dependencies: 0, initial_ranges: 0, name_bytes: 100 * meshes + 4096, upload_bytes: 0,
        edges: 8 * meshes + 64, segments: 4 * meshes + 64, readers: 8 * meshes + 64,
    }, 1).unwrap();
    let mut raw = Vec::with_capacity(9);
    let mut pass_count = 0;
    for sample in 0..WARMUP + 9 {
        let frame = captured.build_graph(&mut pool, true, |g, color| {
            let desc = g.image_desc(color)?;
            let a = g.image("a", desc)?;
            let b = g.image("b", desc)?;
            g.compute("compute.a", color, a, ComputeTransform::Invert)?;
            g.compute("compute.b", a, b, ComputeTransform::SwapRedBlue)?;
            if dead_branch {
                let dead = g.image("dead", desc)?;
                g.compute("dead.compute", color, dead, ComputeTransform::Invert)?;
            }
            Ok(b)
        }).unwrap();
        let started = Instant::now();
        let plan = frame.graph.compile().unwrap();
        let elapsed = started.elapsed().as_nanos();
        pass_count = plan.pass_count();
        assert_eq!(pass_count, 2 * meshes + 4);
        black_box(&plan);
        if sample >= WARMUP { raw.push(elapsed); }
    }
    report(&format!("engine_meshes{meshes}_draws{draws}_dead{dead_branch}"), pass_count, &raw);
}

fn main() {
    #[cfg(windows)]
    pin_measurement_process();
    // Stabilize the pinned process before the first microsecond-scale cases.
    // This is outside every build/compile sample and identical for all variants.
    let warmup = Instant::now();
    let mut warm_state = 1u64;
    while warmup.elapsed() < std::time::Duration::from_millis(100) {
        warm_state = black_box(warm_state.wrapping_mul(6364136223846793005).wrapping_add(1));
    }
    for n in [16, 128, 1024, 2048, 4096, 8192] {
        for order in ["ascending", "descending", "shuffled"] { intervals(n, order, false); }
        for order in ["ascending", "shuffled"] { intervals(n, order, true); }
    }
    for n in [1024, 2048, 4096, 8192, 16384] { dependencies(n); }
    for n in [128, 1024, 8192] {
        fallback_compile(n, false);
        fallback_compile(n, true);
    }
    for (meshes, draws) in [(1, 8192), (128, 1024), (1024, 1024)] {
        engine_graph(meshes, draws, false);
        engine_graph(meshes, draws, true);
    }
}
